vrrp_script chk_haproxy {
    script "/usr/bin/pgrep -x haproxy"
    interval 2
    timeout 2
    fall 2
    rise 2
}

vrrp_instance VI_1 {
    state MASTER
    interface eth0              # replace with your NIC
    virtual_router_id 51
    priority 150
    advert_int 1
    authentication {
        auth_type PASS
        auth_pass changeme1     # max 8 chars
    }
    virtual_ipaddress {
        192.0.2.100/24          # replace with a free IP
    }
    track_script {
        chk_haproxy
    }
}
